import{_ as e,o as t,c as o,aj as r}from"./chunks/framework.BwH0p-pt.js";const p=JSON.parse('{"title":"PIM Concepts & Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/introduction/glossary.md","filePath":"3.0/introduction/glossary.md","lastUpdated":1788942616000}'),i={name:"3.0/introduction/glossary.md"};function n(s,a,c,l,u,h){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="pim-concepts-glossary" tabindex="-1">PIM Concepts &amp; Glossary <a class="header-anchor" href="#pim-concepts-glossary" aria-label="Permalink to &quot;PIM Concepts &amp; Glossary&quot;">​</a></h1><p>New to product information management? This page explains every core UnoPim concept in plain business language. Each entry links to the guide page where you can go deeper.</p><h2 id="attribute" tabindex="-1">Attribute <a class="header-anchor" href="#attribute" aria-label="Permalink to &quot;Attribute&quot;">​</a></h2><p>An attribute is a single piece of information about a product — its name, color, price, or description. You define attributes once and reuse them across the whole catalog, so &quot;Color&quot; always means the same thing everywhere. Learn more in <a href="./../attribute/product-attribute.html">Attributes</a>.</p><h2 id="attribute-family" tabindex="-1">Attribute Family <a class="header-anchor" href="#attribute-family" aria-label="Permalink to &quot;Attribute Family&quot;">​</a></h2><p>A family is the complete template for one kind of product. A &quot;Sofa&quot; family lists different attributes than a &quot;Smartphone&quot; family, and every product must belong to exactly one family. The family decides which fields appear on a product&#39;s edit page and which count toward completeness. Learn more in <a href="./../attribute/attribute-family.html">Attribute Families</a>.</p><h2 id="attribute-group" tabindex="-1">Attribute Group <a class="header-anchor" href="#attribute-group" aria-label="Permalink to &quot;Attribute Group&quot;">​</a></h2><p>An attribute group bundles related attributes — General, Pricing, SEO — into a labeled section. Groups keep long product forms organized so editors find fields quickly. Learn more in <a href="./../attribute/attribute-groups.html">Attribute Groups</a>.</p><h2 id="association-association-type" tabindex="-1">Association / Association Type <a class="header-anchor" href="#association-association-type" aria-label="Permalink to &quot;Association / Association Type&quot;">​</a></h2><p>An association is a link between two products, such as &quot;related&quot;, &quot;cross-sell&quot;, or &quot;up-sell&quot;. Association types define which kinds of links exist, and in UnoPim 3.0 you can create your own — &quot;spare parts&quot;, &quot;accessories&quot;, anything your business needs. Learn more in <a href="./../associations/">Associations</a> and <a href="./../associations/association-types.html">Association Types</a>.</p><h2 id="category" tabindex="-1">Category <a class="header-anchor" href="#category" aria-label="Permalink to &quot;Category&quot;">​</a></h2><p>A category is a folder in the tree that organizes your catalog — Clothing → Men → Shirts. Products can sit in several categories at once, and each sales channel reads from a category tree. Learn more in <a href="./../category/categories.html">Categories</a>.</p><h2 id="category-field" tabindex="-1">Category Field <a class="header-anchor" href="#category-field" aria-label="Permalink to &quot;Category Field&quot;">​</a></h2><p>A category field is extra information you attach to categories themselves — a banner image, a description, an SEO title. Just like product attributes, but for categories. Learn more in <a href="./../categoryField/category-fields.html">Category Fields</a>.</p><h2 id="channel" tabindex="-1">Channel <a class="header-anchor" href="#channel" aria-label="Permalink to &quot;Channel&quot;">​</a></h2><p>A channel is a destination for your product data: a webshop, a mobile app, a marketplace, a print catalog. Each channel combines locales, currencies, and a category tree, so you can tailor what each destination receives. Learn more in <a href="./../settings/channels.html">Channels</a>.</p><h2 id="completeness" tabindex="-1">Completeness <a class="header-anchor" href="#completeness" aria-label="Permalink to &quot;Completeness&quot;">​</a></h2><p>Completeness is a score that shows how ready a product is for publication — the share of required attributes that are actually filled in, per channel and per locale. It turns &quot;is this product done?&quot; into a number your team can act on. Learn more in <a href="./../products/">Products</a>.</p><h2 id="configurable-product-variant" tabindex="-1">Configurable Product / Variant <a class="header-anchor" href="#configurable-product-variant" aria-label="Permalink to &quot;Configurable Product / Variant&quot;">​</a></h2><p>A configurable product is a parent that comes in several versions — a T-shirt in sizes and colors. Each concrete version (Red / M) is a variant with its own SKU. Shared data lives on the parent; only the differences live on the variants. Learn more in <a href="./../products/configurable.html">Configurable Products</a> and <a href="./../products/variants.html">Variants</a>.</p><h2 id="currency" tabindex="-1">Currency <a class="header-anchor" href="#currency" aria-label="Permalink to &quot;Currency&quot;">​</a></h2><p>A currency (EUR, USD, INR) gives meaning to price attributes. Enable the currencies you sell in, and every price field lets you enter a value per currency. Learn more in <a href="./../settings/currencies.html">Currencies</a>.</p><h2 id="digital-product-passport" tabindex="-1">Digital Product Passport <a class="header-anchor" href="#digital-product-passport" aria-label="Permalink to &quot;Digital Product Passport&quot;">​</a></h2><p>A Digital Product Passport (DPP) is a public web page that proves what a product is made of, how it complies with regulations, and how to repair or recycle it — increasingly required by EU law. UnoPim builds these pages from your existing product data and publishes them with a QR code. Learn more in <a href="./../passport/">Product Passports</a>.</p><h2 id="import-export-job" tabindex="-1">Import / Export Job <a class="header-anchor" href="#import-export-job" aria-label="Permalink to &quot;Import / Export Job&quot;">​</a></h2><p>An import or export job is a saved profile that moves data in or out of UnoPim — a CSV of products in, an Excel of enriched data out. Jobs run in the background, can be tracked live, and can be reused as often as you like. Learn more in <a href="./../data-transfer/import.html">Import</a> and <a href="./../data-transfer/export.html">Export</a>.</p><h2 id="integration-robot-user" tabindex="-1">Integration (robot user) <a class="header-anchor" href="#integration-robot-user" aria-label="Permalink to &quot;Integration (robot user)&quot;">​</a></h2><p>An integration is a machine account — a &quot;robot user&quot; — that lets another system talk to the UnoPim API with its own credentials and permissions. Your ERP or webshop connects as an integration, never with a person&#39;s login. Learn more in <a href="./../configuration/integration.html">Integrations</a>.</p><h2 id="locale" tabindex="-1">Locale <a class="header-anchor" href="#locale" aria-label="Permalink to &quot;Locale&quot;">​</a></h2><p>A locale is a language-and-region combination such as <code>en_US</code> or <code>de_DE</code>. Product content is stored per locale, so one product can carry an English and a German description side by side. Learn more in <a href="./../settings/locale.html">Locales</a>.</p><h2 id="measurement-family-unit" tabindex="-1">Measurement Family / Unit <a class="header-anchor" href="#measurement-family-unit" aria-label="Permalink to &quot;Measurement Family / Unit&quot;">​</a></h2><p>A measurement family groups units that convert into each other — Weight holds kg, g, and lb. Attach a family to a numeric attribute and editors can enter a value in any unit, with conversion handled for them. Learn more in <a href="./../measurements/">Measurements</a>.</p><h2 id="product" tabindex="-1">Product <a class="header-anchor" href="#product" aria-label="Permalink to &quot;Product&quot;">​</a></h2><p>A product is the central record in the PIM: one item you sell or manage, identified by its SKU and shaped by its family. Everything else — attributes, categories, channels, associations — exists to describe, organize, and distribute products. Learn more in <a href="./../products/">Products</a>.</p><h2 id="saved-view" tabindex="-1">Saved View <a class="header-anchor" href="#saved-view" aria-label="Permalink to &quot;Saved View&quot;">​</a></h2><p>A saved view remembers a product grid setup — filters, columns, sorting — under a name, so you can return to &quot;Incomplete winter items&quot; with one click and share it with colleagues. Learn more in <a href="./../products/filters-and-views.html">Filters &amp; Saved Views</a>.</p><h2 id="sku" tabindex="-1">SKU <a class="header-anchor" href="#sku" aria-label="Permalink to &quot;SKU&quot;">​</a></h2><p>The SKU (Stock Keeping Unit) is a product&#39;s unique code — its identity across UnoPim, your ERP, and your shops. Every product has exactly one, and no two products share it. Learn more in <a href="./../products/simple.html">Simple Products</a>.</p><h2 id="variant-axis" tabindex="-1">Variant Axis <a class="header-anchor" href="#variant-axis" aria-label="Permalink to &quot;Variant Axis&quot;">​</a></h2><p>A variant axis is the attribute a configurable product varies by — size, color, or both. The axes decide how many variants exist and guarantee no two variants share the same combination. Learn more in <a href="./../products/variants.html">Variants</a>.</p><h2 id="webhook" tabindex="-1">Webhook <a class="header-anchor" href="#webhook" aria-label="Permalink to &quot;Webhook&quot;">​</a></h2><p>A webhook is an automatic notification UnoPim sends to another system when something changes — a product is updated, so your webshop hears about it within seconds. No polling, no manual exports. Learn more in <a href="./../configuration/webhooks.html">Webhooks</a>.</p>',42)])])}const m=e(i,[["render",n]]);export{p as __pageData,m as default};
